//! Stage 2a: byte-validity filtering by real decoding.
//!
//! The reference runs one whole-window decode per candidate with
//! `final=False`, which tolerates an incomplete multi-byte sequence at the
//! very end (the input is usually a prefix of a larger whole) but rejects
//! corruption anywhere else.
//!
//! Rust has no codec for every encoding the registry lists, so the check
//! picks the best available answer per candidate:
//!
//! * single-byte code pages validate against the generated byte tables (a
//!   byte is invalid exactly where the reference's codec raises);
//! * multi-byte codecs `encoding_rs` knows validate by a strict decode with
//!   the same trailing tolerance;
//! * everything else (EUC-JIS-2004, Shift_JIS-2004, ISO-2022 variants,
//!   Johab) is left to the structural stage's judgment.
//!
//! This supersedes the byte-pattern heuristics in
//! [`crate::pipeline::validity`] as the pipeline's validity stage.

use crate::encoding_tables::{byte_pairs_for, tables_for, BytePairs, UNDECODABLE_CHAR_ID};
use crate::registry::{EncodingInfo, REGISTRY};

/// Encodings whose Python codec insists on a BOM; the BOM stage owns them.
const BOM_ONLY_ENCODINGS: [&str; 2] = ["utf-16", "utf-32"];

/// Encodings that spend more than one byte per character but are not CJK.
const NON_CJK_MULTIBYTE: [&str; 4] = ["utf-8", "utf-8-sig", "utf-16", "utf-32"];

/// Whether *encoding* uses a single byte per character.
fn is_single_byte(encoding: &str) -> bool {
    // Every UTF variant spends more than one byte per character, and the
    // generated per-byte tables cannot answer for them.
    if NON_CJK_MULTIBYTE.contains(&encoding) || encoding.starts_with("utf-") {
        return false;
    }
    match REGISTRY.get(encoding) {
        Some(info) => !info.is_multibyte_cjk,
        None => false,
    }
}

/// Filter candidates to those that can decode the data without errors.
pub fn filter_by_validity<'a>(
    data: &[u8],
    candidates: &[&'a EncodingInfo],
) -> Vec<&'a EncodingInfo> {
    if data.is_empty() {
        return candidates.to_vec();
    }

    candidates
        .iter()
        .copied()
        .filter(|enc| decodes_without_error(data, enc.name))
        .collect()
}

/// Whether *data* decodes under *encoding*, tolerating a cut final sequence.
pub fn decodes_without_error(data: &[u8], encoding: &str) -> bool {
    if BOM_ONLY_ENCODINGS.contains(&encoding) {
        return false;
    }

    if is_single_byte(encoding) {
        if let Some(tables) = tables_for(encoding) {
            return data
                .iter()
                .all(|&byte| tables.char_id[byte as usize] != UNDECODABLE_CHAR_ID);
        }
        return true;
    }

    if let Some(pairs) = byte_pairs_for(encoding) {
        return decodes_with_pairs(data, pairs, encoding);
    }

    if let Some(codec) = encoding_rs::Encoding::for_label(encoding.as_bytes()) {
        // Strict whole-window decode, then the same check with up to three
        // bytes trimmed: a multi-byte character cut by the end of the input is
        // tolerated, corruption anywhere else is not.
        for trim in 0..=3usize {
            if trim >= data.len() {
                break;
            }
            let window = &data[..data.len() - trim];
            if codec
                .decode_without_bom_handling_and_without_replacement(window)
                .is_some()
            {
                return true;
            }
        }
        return false;
    }

    // No codec available: the structural stage's view stands.
    true
}

/// Whether *data* decodes under a generated byte-pair grammar.
///
/// A sequence cut by the end of the input is tolerated, as everywhere else;
/// corruption anywhere else is not.  EUC-style three-byte sequences (lead
/// ``0x8F``) and the GB18030 four-byte form are rules rather than table
/// entries, so they are checked explicitly.
fn decodes_with_pairs(data: &[u8], pairs: &BytePairs, encoding: &str) -> bool {
    let three_byte_lead = matches!(encoding, "euc_jp" | "euc_jis_2004");
    let four_byte_gb = encoding == "gb18030";
    let mut i = 0usize;
    while i < data.len() {
        let lead = data[i];
        if lead < 0x80 {
            i += 1;
            continue;
        }
        if three_byte_lead && lead == 0x8F {
            if i + 2 >= data.len() {
                return true;
            }
            if !(0xA1..=0xFE).contains(&data[i + 1]) || !(0xA1..=0xFE).contains(&data[i + 2]) {
                return false;
            }
            i += 3;
            continue;
        }
        if four_byte_gb && i + 1 < data.len() && (0x30..=0x39).contains(&data[i + 1]) {
            if i + 3 >= data.len() {
                return true;
            }
            if !(0x81..=0xFE).contains(&data[i + 2]) || !(0x30..=0x39).contains(&data[i + 3]) {
                return false;
            }
            i += 4;
            continue;
        }
        // A codec either completes a character with this byte (half-width
        // katakana in Shift_JIS) or needs a trail byte, exactly as Python's
        // decoder decides it.
        if pairs.single_ok(lead) {
            i += 1;
            continue;
        }
        if i + 1 >= data.len() {
            // A pair cut by the end of the input.
            return true;
        }
        if !pairs.pair_ok(lead, data[i + 1]) {
            return false;
        }
        i += 2;
    }
    true
}

/// Whole-window soundness for a UTF-16 byte order: no unpaired surrogates.
///
/// A final unit cut by the window is tolerated, as everywhere else; an
/// unpaired surrogate anywhere else is corruption.
#[allow(clippy::chunks_exact_to_as_chunks)] // pairs are read positionally; as_chunks would obscure the surrogate lookahead
pub fn utf16_window_ok(data: &[u8], big_endian: bool) -> bool {
    let usable = data.len() - (data.len() % 2);
    let units = data[..usable].chunks_exact(2);
    let mut pending_high = false;
    for unit in units {
        let value = if big_endian {
            u16::from_be_bytes([unit[0], unit[1]])
        } else {
            u16::from_le_bytes([unit[0], unit[1]])
        };
        if pending_high {
            if !(0xDC00..=0xDFFF).contains(&value) {
                return false;
            }
            pending_high = false;
            continue;
        }
        if (0xD800..=0xDBFF).contains(&value) {
            pending_high = true;
        } else if (0xDC00..=0xDFFF).contains(&value) {
            return false;
        }
    }
    true
}

/// Whole-window soundness for a UTF-32 byte order: every unit in range.
pub fn utf32_window_ok(data: &[u8], big_endian: bool) -> bool {
    data.as_chunks::<4>().0.iter().all(|unit| {
        let value = if big_endian {
            u32::from_be_bytes([unit[0], unit[1], unit[2], unit[3]])
        } else {
            u32::from_le_bytes([unit[0], unit[1], unit[2], unit[3]])
        };
        value <= 0x10FFFF && !(0xD800..=0xDFFF).contains(&value)
    })
}
